/* FACTS: { id, d: domain, n: study-notes section id, q: front, a: back }.
   `a` is a string, or a list of [label, text] rows for a back with parts. */
export const FACTS = [
  /* ---------------- Airway & Respiratory ---------------- */
  { id: 'air-headtilt', d: 'airway', n: 'ch9-airway', q: 'Which manual airway maneuver do you use when spinal injury is suspected?', a: 'Jaw-thrust maneuver, without head tilt. Head-tilt chin-lift is for patients with no suspected spinal injury. If the jaw thrust does not open the airway, the airway wins.' },
  { id: 'air-opa-size', d: 'airway', n: 'ch9-adjuncts', q: 'How do you size an oropharyngeal airway (OPA)?', a: 'From the corner of the mouth to the earlobe (or the angle of the jaw).' },
  { id: 'air-opa-who', d: 'airway', n: 'ch9-adjuncts', q: 'Who can take an OPA?', a: 'Only an unresponsive patient with no gag reflex. If the patient gags, remove it.' },
  { id: 'air-opa-insert', d: 'airway', n: 'ch9-adjuncts', q: 'How is an OPA inserted in an adult?', a: 'Tip toward the roof of the mouth, then rotated 180° into place as it reaches the back of the tongue (or inserted sideways and rotated 90°). In a child, insert it right side up with a tongue depressor.' },
  { id: 'air-npa-size', d: 'airway', n: 'ch9-adjuncts', q: 'How do you size a nasopharyngeal airway (NPA)?', a: 'From the tip of the nose to the earlobe, with a diameter that fits the nostril. Lubricate with a water-soluble lubricant; bevel toward the septum, larger (usually right) nostril first.' },
  { id: 'air-npa-who', d: 'airway', n: 'ch9-adjuncts', q: 'Main advantage of an NPA over an OPA?', a: 'It is tolerated by a patient who still has a gag reflex (e.g. a semi-responsive patient).' },
  { id: 'air-npa-avoid', d: 'airway', n: 'ch9-adjuncts', q: 'When should you avoid an NPA?', a: 'Suspected basilar skull fracture or severe facial/nasal trauma (e.g. CSF from the nose or ears, raccoon eyes, Battle sign).' },
  { id: 'air-suction-time', d: 'airway', n: 'ch9-suction', q: 'Maximum suction time per attempt?', a: [['Adult', 'About 15 seconds'], ['Child or infant', 'About 10 seconds or less, at lower pressure'], ['Note', 'Pre-oxygenate, and ventilate between attempts. Local protocol sets the exact figure.']] },
  { id: 'air-suction-how', d: 'airway', n: 'ch9-suction', q: 'When is suction applied — going in, or coming out?', a: 'Coming out. Insert the rigid tip only as far as you can see, then suction while withdrawing.' },
  { id: 'air-gurgling', d: 'airway', n: 'ch9-suction', q: 'What does gurgling in the airway tell you to do?', a: 'Suction. Gurgling means fluid (blood, vomit, secretions) in the upper airway.' },
  { id: 'air-snoring', d: 'airway', n: 'ch9-suction', q: 'What does snoring respiration usually mean, and the fix?', a: 'The tongue is partly blocking the upper airway. Reposition the airway (head-tilt chin-lift or jaw thrust) and consider an adjunct.' },
  { id: 'air-fbao-adult', d: 'airway', n: 'ch9-fbao', q: 'Responsive adult or child with a severe airway obstruction (AHA 2025): the sequence?', a: 'Five back blows, then five abdominal thrusts, repeated until the object comes out or the patient becomes unresponsive.' },
  { id: 'air-fbao-infant', d: 'airway', n: 'ch9-fbao', q: 'Responsive infant with a severe airway obstruction: the sequence?', a: 'Five back blows, then five chest thrusts (never abdominal thrusts), repeated.' },
  { id: 'air-fbao-preg', d: 'airway', n: 'ch9-fbao', q: 'Choking patient who is obviously pregnant or too large to reach around: what replaces abdominal thrusts?', a: 'Chest thrusts.' },
  { id: 'air-fbao-unresp', d: 'airway', n: 'ch9-fbao', q: 'The choking patient becomes unresponsive. What now?', a: 'Lower them to the ground and begin CPR, starting with compressions. Each time you open the airway, look in the mouth and remove an object you can see. No blind finger sweeps.' },
  { id: 'air-fbao-mild', d: 'airway', n: 'ch9-fbao', q: 'A choking patient can cough forcefully and speak. What do you do?', a: 'Encourage them to keep coughing and watch closely. Do not intervene unless the obstruction becomes severe (weak or silent cough, cannot speak, cyanosis).' },
  { id: 'air-bvm-twoperson', d: 'airway', n: 'ch9-bvm', q: 'One-rescuer or two-rescuer BVM ventilation — which is preferred, and why?', a: 'Two-rescuer: one seals the mask with both hands, the other squeezes the bag. It delivers measurably more volume.' },
  { id: 'air-bvm-ec', d: 'airway', n: 'ch9-bvm', q: 'What is the E-C clamp?', a: 'The one-hand mask seal: thumb and index finger form a C pressing the mask to the face; the other three fingers form an E lifting the jaw into the mask.' },
  { id: 'air-bvm-breath', d: 'airway', n: 'ch9-bvm', q: 'How long and how big should each ventilation be?', a: 'Over about 1 second, just enough to see the chest rise. Bigger or faster breaths inflate the stomach.' },
  { id: 'air-bvm-o2', d: 'airway', n: 'ch10-delivery-devices', q: 'Oxygen flow to a BVM with reservoir, and the concentration it gives?', a: '15 L/min; nearly 100% oxygen.' },
  { id: 'air-rate-adult', d: 'airway', n: 'ch21-steps', q: 'Rescue breathing rate for an adult with a pulse who is not breathing adequately?', a: 'One breath every 6 seconds — about 10 per minute.' },
  { id: 'air-rate-peds', d: 'airway', n: 'ch21-steps', q: 'Rescue breathing rate for an infant or child with a pulse?', a: 'One breath every 2–3 seconds — about 20–30 per minute.' },
  { id: 'air-gastric', d: 'airway', n: 'ch9-bvm', q: 'What causes gastric distention during ventilation, and why does it matter?', a: 'Breaths that are too large or too fast. Air in the stomach pushes up on the diaphragm, makes ventilation harder and raises the risk of vomiting and aspiration.' },
  { id: 'air-o2-vs-vent', d: 'airway', n: 'ch10-oxygen-or-ventilation', q: 'Patient breathing 6 times a minute with shallow chest rise. Non-rebreather or BVM?', a: 'BVM. The problem is volume, not oxygen concentration — a non-rebreather enriches a breath too small to matter. Ventilate, with oxygen through the bag.' },
  { id: 'air-quiet', d: 'airway', n: 'ch10-oxygen-or-ventilation', q: 'A patient in severe respiratory distress suddenly becomes quiet and sleepy. What does it mean?', a: 'Exhaustion and rising CO₂ — respiratory failure, not improvement. Be ready to ventilate.' },
  { id: 'air-assist-timing', d: 'airway', n: 'ch10-oxygen-or-ventilation', q: 'Assisting ventilations for a patient who still breathes on their own: when do you squeeze?', a: 'At the start of the patient’s own inhalation. Squeezing as they exhale fights them and forces air into the stomach.' },
  { id: 'air-nc', d: 'airway', n: 'ch10-delivery-devices', q: 'Nasal cannula: flow rate and approximate oxygen?', a: '1–6 L/min; about 24–44%.' },
  { id: 'air-nrb', d: 'airway', n: 'ch10-delivery-devices', q: 'Non-rebreather mask: flow rate and approximate oxygen?', a: '10–15 L/min; about 80–90%. Inflate the reservoir bag before it goes on the patient, and keep it from collapsing as they breathe.' },
  { id: 'air-simple-mask', d: 'airway', n: 'ch10-delivery-devices', q: 'Simple face mask: flow rate and approximate oxygen?', a: '6–10 L/min; about 35–60%.' },
  { id: 'air-spo2-target', d: 'airway', n: 'ch10-delivery-devices', q: 'Usual SpO₂ target when giving oxygen?', a: 'About 94% or above for most patients. Titrate to the target rather than giving high flow to everyone.' },
  { id: 'air-copd-target', d: 'airway', n: 'ch10-delivery-devices', q: 'SpO₂ target for a patient with known COPD — and does a hypoxic COPD patient get oxygen?', a: 'About 88–92%. Yes: the lower target is a reason to titrate, never to withhold.' },
  { id: 'air-venturi', d: 'airway', n: 'ch10-oxygen-equipment', q: 'What does a Venturi mask do that other masks do not?', a: 'Delivers a precise, fixed oxygen concentration — useful in COPD, where the goal is enough oxygen and not more.' },
  { id: 'air-cyl-full', d: 'airway', n: 'ch10-oxygen-equipment', q: 'Pressure in a full oxygen cylinder, and the safe residual pressure?', a: 'About 2,000 psi full. Change the cylinder at about 200 psi (the safe residual).' },
  { id: 'air-pin-index', d: 'airway', n: 'ch10-oxygen-equipment', q: 'What is the pin-index safety system for?', a: 'It stops the wrong regulator from being fitted to the wrong gas cylinder.' },
  { id: 'air-regulator', d: 'airway', n: 'ch10-oxygen-equipment', q: 'Regulator vs. flowmeter: which does what?', a: 'The regulator steps cylinder pressure down to a usable level; the flowmeter sets and shows the liters per minute delivered.' },
  { id: 'air-o2-fire', d: 'airway', n: 'ch10-oxygen-equipment', q: 'Why keep oil, grease and adhesive tape away from oxygen fittings?', a: 'Oxygen dramatically accelerates combustion; petroleum products near it are a fire hazard.' },
  { id: 'air-cpap-ind', d: 'airway', n: 'ch19-conditions', q: 'CPAP is used for which kind of patient?', a: 'An awake patient in respiratory distress who is still breathing on their own and can follow commands — e.g. pulmonary edema (CHF), COPD, asthma, drowning.' },
  { id: 'air-cpap-contra', d: 'airway', n: 'ch19-conditions', q: 'Name the main contraindications to CPAP.', a: 'Depressed mental status or not breathing on their own, unable to sit up or protect the airway, hypotension, suspected pneumothorax or chest trauma, facial trauma, active vomiting.' },
  { id: 'air-cpap-pressure', d: 'airway', n: 'ch19-conditions', q: 'How does CPAP help, and the typical pressure?', a: 'PEEP keeps small airways and alveoli open at the end of each breath; typical range 5–15 cm H₂O (start low, per protocol).' },
  { id: 'air-adequate', d: 'airway', n: 'ch19-respiratory', q: 'Normal adult respiratory rate at rest?', a: '12–20 breaths per minute.' },
  { id: 'air-inadequate-signs', d: 'airway', n: 'ch19-respiratory', q: 'Signs of inadequate breathing?', a: 'Rate too fast or too slow, shallow or absent chest rise, diminished breath sounds, cyanosis, altered mental status, speaking only a word or two; in children nasal flaring, retractions, grunting, head bobbing.' },
  { id: 'air-asthma', d: 'airway', n: 'ch19-conditions', q: 'Asthma: what happens in the airways?', a: 'Small airways constrict and fill with mucus; exhaling is harder than inhaling, so air is trapped. Wheezing on expiration is classic.' },
  { id: 'air-silent-chest', d: 'airway', n: 'ch19-conditions', q: 'An asthmatic’s wheezing stops but they still look exhausted. Good sign?', a: 'No — a "silent chest" can mean so little air is moving that it cannot wheeze. Prepare to ventilate.' },
  { id: 'air-albuterol', d: 'airway', n: 'ch18-pharmacology', q: 'Albuterol: what does it do, and its common side effects?', a: 'A beta-2 agonist bronchodilator that relaxes airway smooth muscle. Side effects: increased heart rate, jitteriness.' },
  { id: 'air-inhaler-rules', d: 'airway', n: 'ch18-pharmacology', q: 'Before helping a patient use their metered-dose inhaler, confirm what?', a: 'It is prescribed to this patient, not expired, the patient can use it, and you have medical direction (online or standing order).' },
  { id: 'air-maintenance', d: 'airway', n: 'ch18-pharmacology', q: 'Can a daily maintenance inhaler (e.g. a steroid such as Advair) reverse an acute asthma attack?', a: 'No. Maintenance inhalers prevent attacks; they are not rescue medications.' },
  { id: 'air-croup', d: 'airway', n: 'ch19-conditions', q: 'Croup: classic picture?', a: 'Viral, usually in toddlers; gradual onset, low-grade fever, a barking (seal-like) cough and stridor, often worse at night.' },
  { id: 'air-epiglottitis', d: 'airway', n: 'ch19-conditions', q: 'Epiglottitis: classic picture and the key "don’t"?', a: 'Sudden high fever, sore throat, drooling, difficulty swallowing, tripod position, stridor. Do not put anything in the mouth or examine the throat — it can trigger complete obstruction. Keep the patient calm and sitting up.' },
  { id: 'air-pe', d: 'airway', n: 'ch19-conditions', q: 'Pulmonary embolism: typical presentation?', a: 'Sudden shortness of breath and sharp chest pain worse on breathing, tachycardia, sometimes coughing blood — often with risk factors such as immobility, recent surgery, long travel or DVT.' },
  { id: 'air-spont-ptx', d: 'airway', n: 'ch19-conditions', q: 'Spontaneous pneumothorax: who classically gets it?', a: 'Tall, thin young men (and people with lung disease such as COPD); sudden one-sided chest pain and shortness of breath.' },
  { id: 'air-hypervent', d: 'airway', n: 'ch19-conditions', q: 'Hyperventilation syndrome: signs, and why is a paper bag wrong?', a: 'Numbness and tingling around the mouth and in the hands, carpopedal spasm. Rebreathing into a bag is not used: a serious cause (PE, DKA, MI) can look the same, and the bag can make the patient hypoxic.' },
  { id: 'air-copd', d: 'airway', n: 'ch19-conditions', q: 'COPD covers which two diseases?', a: 'Emphysema (alveolar walls destroyed) and chronic bronchitis (inflamed airways producing mucus).' },
  { id: 'air-pulm-edema', d: 'airway', n: 'ch19-conditions', q: 'Pulmonary edema: what you hear and see?', a: 'Crackles (rales), shortness of breath worse lying flat, sometimes pink frothy sputum — often from left-sided heart failure.' },
  { id: 'air-co-spo2', d: 'airway', n: 'ch13-vital-signs', q: 'Why can a pulse oximeter read normal in carbon monoxide poisoning?', a: 'It cannot tell carbon monoxide bound to hemoglobin from oxygen. Give high-flow oxygen regardless of the reading.' },
  { id: 'air-tripod', d: 'airway', n: 'ch19-respiratory', q: 'A patient sitting upright, leaning forward on their hands. What does that posture tell you?', a: 'Tripod position — significant respiratory distress.' },
  { id: 'air-trach', d: 'airway', n: 'ch37-devices', q: 'A patient with a tracheostomy tube is in distress. Most common fix?', a: 'Suction the tube — the commonest problem is a mucus plug. Ventilate through the stoma or tube if needed.' },
  { id: 'air-stoma', d: 'airway', n: 'ch37-devices', q: 'How do you ventilate a patient who breathes through a stoma?', a: 'Seal an infant or child mask over the stoma (and close the mouth and nose if air escapes) and ventilate with a BVM.' },
  { id: 'air-oxygen-drug', d: 'airway', n: 'ch18-pharmacology', q: 'Is oxygen a medication?', a: 'Yes. It has indications (hypoxia or risk of hypoxia), is given at a set flow, and is withheld when there is no reason to give it.' },
  { id: 'air-anatomy-upper', d: 'airway', n: 'ch9-airway', q: 'What separates the upper from the lower airway?', a: 'The vocal cords, in the larynx. Above them: nose, mouth, pharynx. Below: trachea, bronchi, bronchioles, alveoli.' },
  { id: 'air-epiglottis', d: 'airway', n: 'ch9-airway', q: 'What does the epiglottis do?', a: 'A leaf-shaped flap that closes over the opening of the larynx during swallowing, so food goes to the esophagus, not the trachea.' },
  { id: 'air-peds-airway', d: 'airway', n: 'ch9-airway', q: 'Name three ways a child’s airway differs from an adult’s.', a: 'Larger tongue for the mouth, a smaller and softer trachea that kinks with overextension, and a large occiput that flexes the neck when supine (pad under the shoulders). Infants breathe mainly through the nose.' },

  /* ---------------- Cardiac & Medical ---------------- */
  { id: 'car-cpr-rate', d: 'cardiac', n: 'ch21-steps', q: 'Chest compression rate, all ages?', a: '100–120 per minute.' },
  { id: 'car-depth-adult', d: 'cardiac', n: 'ch21-steps', q: 'Compression depth for an adult?', a: '2 to 2.4 inches (5–6 cm), with full recoil.' },
  { id: 'car-depth-child', d: 'cardiac', n: 'ch21-steps', q: 'Compression depth for a child, and for an infant?', a: 'Child: about 2 inches. Infant: about 1.5 inches. Both are about one third of the chest’s depth.' },
  { id: 'car-ratio', d: 'cardiac', n: 'ch21-steps', q: 'Compression-to-ventilation ratio?', a: [['Adult', '30:2, one or two rescuers'], ['Child or infant, one rescuer', '30:2'], ['Child or infant, two rescuers', '15:2']] },
  { id: 'car-infant-hands', d: 'cardiac', n: 'ch21-steps', q: 'Infant compressions under the 2025 AHA guidelines: which techniques?', a: 'Two thumbs encircling the chest, or the heel of one hand. The two-finger technique was dropped because it does not reliably reach a third of the chest depth.' },
  { id: 'car-adv-airway', d: 'cardiac', n: 'ch21-steps', q: 'CPR with an advanced airway in place: compressions and ventilations?', a: 'Continuous compressions at 100–120/min, no pauses for breaths; one breath every 6 seconds (about 10/min) in an adult, every 2–3 seconds in an infant or child.' },
  { id: 'car-pulse-check', d: 'cardiac', n: 'ch21-steps', q: 'How long may a pulse check take?', a: 'No more than 10 seconds. If you are not sure there is a pulse, start compressions.' },
  { id: 'car-pulse-site', d: 'cardiac', n: 'ch21-steps', q: 'Where do you check the pulse in an unresponsive adult, child and infant?', a: 'Adult: carotid. Child: carotid or femoral. Infant: brachial.' },
  { id: 'car-peds-60', d: 'cardiac', n: 'ch21-steps', q: 'An infant or child has a pulse but it is under 60/min with poor perfusion despite good ventilation. What do you do?', a: 'Start chest compressions.' },
  { id: 'car-agonal', d: 'cardiac', n: 'ch21-arrest-pathophys', q: 'Agonal gasps in an unresponsive patient: breathing or not?', a: 'Not breathing. With no pulse (or if unsure), start compressions.' },
  { id: 'car-switch', d: 'cardiac', n: 'ch21-steps', q: 'How often should compressors switch?', a: 'At least every 2 minutes (at the rhythm check), because compression quality falls as you tire.' },
  { id: 'car-chain', d: 'cardiac', n: 'ch21-arrest-pathophys', q: 'The 2025 chain of survival — the six links?', a: '1 Recognition and emergency activation, 2 high-quality CPR, 3 defibrillation, 4 advanced resuscitation, 5 post–cardiac arrest care, 6 recovery and survivorship. One chain for adults and children, in and out of hospital.' },
  { id: 'car-two-things', d: 'cardiac', n: 'ch21-arrest-pathophys', q: 'Which two interventions most reliably change cardiac arrest outcomes?', a: 'High-quality chest compressions and early defibrillation — both within EMT scope.' },
  { id: 'car-aed-pads', d: 'cardiac', n: 'ch21-steps', q: 'AED pad placement problems: what do you do about a medication patch, a wet chest and an implanted pacemaker?', a: 'Remove the patch and wipe the skin; dry the chest; place the pad several inches away from the pacemaker.' },
  { id: 'car-aed-analysis', d: 'cardiac', n: 'ch21-steps', q: 'After an AED shock, what is the very next action?', a: 'Resume compressions immediately, without a pulse check. The AED reanalyzes in about 2 minutes.' },
  { id: 'car-aed-peds', d: 'cardiac', n: 'ch21-steps', q: 'AED on a child: which pads?', a: 'Pediatric pads (dose-attenuated) for a child under 8 if available, often front-and-back. If there are none, use adult pads — do not withhold the shock.' },
  { id: 'car-aed-lone-peds', d: 'cardiac', n: 'ch21-steps', q: 'Lone rescuer, unwitnessed arrest of a child: CPR or AED first?', a: 'About 2 minutes of CPR first, then get the AED — pediatric arrests are usually asphyxial. With an AED at hand or a crew, attach it as soon as it arrives.' },
  { id: 'car-aed-moving', d: 'cardiac', n: 'ch21-special', q: 'Arrest during transport — what about the moving ambulance?', a: 'Stop the vehicle to do CPR and use the AED; motion degrades compressions and some AEDs cannot analyze while moving.' },
  { id: 'car-vf', d: 'cardiac', n: 'ch21-arrest-pathophys', q: 'Which rhythms does an AED shock?', a: 'Ventricular fibrillation and pulseless ventricular tachycardia. Not asystole or PEA.' },
  { id: 'car-pea', d: 'cardiac', n: 'ch21-arrest-pathophys', q: 'What is PEA?', a: 'Pulseless electrical activity: an organized rhythm on the monitor but no pulse. Not shockable; continue CPR.' },
  { id: 'car-rosc', d: 'cardiac', n: 'ch21-steps', q: 'After ROSC: oxygen saturation target?', a: '92–98%. Avoid both hypoxia and hyperoxia, and avoid hyperventilating.' },
  { id: 'car-stop-cpr', d: 'cardiac', n: 'ch21-steps', q: 'Once started, when may CPR stop?', a: 'Pulse returns; care is handed to equal or higher trained providers; you are too exhausted to continue (or the scene becomes unsafe); or a physician or other authority orders it stopped.' },
  { id: 'car-lvad', d: 'cardiac', n: 'ch21-special', q: 'Patient with an LVAD: what is unusual about the pulse?', a: 'There may be no palpable pulse or measurable BP even in a living patient. Judge by mental status and breathing; call the VAD team number on the device.' },
  { id: 'car-icd', d: 'cardiac', n: 'ch21-special', q: 'An implanted defibrillator is firing. Is touching the patient dangerous?', a: 'No meaningful danger to you. Treat the firing as a serious sign, transport, and place AED pads away from the device if needed.' },
  { id: 'car-acs', d: 'cardiac', n: 'ch20-acs', q: 'Classic signs of acute coronary syndrome?', a: 'Chest pressure or squeezing, often radiating to the arm, jaw or back, with shortness of breath, sweating, nausea or anxiety.' },
  { id: 'car-atypical', d: 'cardiac', n: 'ch20-acs', q: 'Which patients often have an MI without classic chest pain?', a: 'Women, older adults and people with diabetes — they may have only weakness, fatigue, shortness of breath or nausea.' },
  { id: 'car-aspirin', d: 'cardiac', n: 'ch18-pharmacology', q: 'Aspirin for suspected cardiac chest pain: dose and how it is given?', a: 'Commonly 162–324 mg (two to four 81 mg tablets), chewed. Per local protocol.' },
  { id: 'car-aspirin-contra', d: 'cardiac', n: 'ch18-pharmacology', q: 'Contraindications to aspirin?', a: 'Allergy to aspirin and GI bleeding (and inability to swallow safely).' },
  { id: 'car-nitro-dose', d: 'cardiac', n: 'ch18-pharmacology', q: 'Nitroglycerin: usual dose, route and repeat?', a: 'Commonly 0.4 mg sublingual (tablet or spray), repeated every 5 minutes up to 3 doses if BP allows — the patient’s own prescription, with medical direction, per protocol.' },
  { id: 'car-nitro-contra', d: 'cardiac', n: 'ch18-pharmacology', q: 'When must nitroglycerin not be given?', a: 'Low blood pressure (below the protocol’s floor, commonly 100 systolic), recent erectile-dysfunction medication (sildenafil or vardenafil in 24 h, tadalafil in 48 h), suspected right-ventricular infarction, head injury, or the maximum dose already taken.' },
  { id: 'car-nitro-side', d: 'cardiac', n: 'ch18-pharmacology', q: 'Most important side effect of nitroglycerin, and what you do?', a: 'Hypotension (also headache). Lay the patient flat and recheck BP after each dose.' },
  { id: 'car-angina-vs-mi', d: 'cardiac', n: 'ch20-cad-ami-hf', q: 'Stable angina vs. myocardial infarction?', a: 'Angina: brief ischemia, usually relieved by rest or nitroglycerin. MI: heart muscle dying, pain persists despite rest and nitro. You cannot tell them apart in the field — treat as ACS.' },
  { id: 'car-chf-left', d: 'cardiac', n: 'ch20-cad-ami-hf', q: 'Left-sided heart failure backs fluid up into where?', a: 'The lungs: pulmonary edema, crackles, orthopnea.' },
  { id: 'car-chf-right', d: 'cardiac', n: 'ch20-cad-ami-hf', q: 'Right-sided heart failure shows up where?', a: 'In the body: jugular vein distention, swelling of the feet and ankles (pedal edema), enlarged liver.' },
  { id: 'car-cardiogenic', d: 'cardiac', n: 'ch20-cad-ami-hf', q: 'Cardiogenic shock: what fails?', a: 'The heart cannot pump enough blood (often after a large MI): hypotension, pulmonary edema, cool clammy skin.' },
  { id: 'car-aaa', d: 'cardiac', n: 'ch26-abdominal', q: 'Abdominal aortic aneurysm rupture: classic presentation?', a: 'Sudden severe abdominal or back pain, often described as tearing, with signs of shock; sometimes a pulsating abdominal mass or unequal leg pulses.' },
  { id: 'car-dissection', d: 'cardiac', n: 'ch20-cad-ami-hf', q: 'Aortic dissection: classic pain?', a: 'Sudden, severe tearing or ripping chest pain that radiates to the back, between the shoulder blades; BP may differ between the arms.' },
  { id: 'car-glucose-low', d: 'cardiac', n: 'ch22-ams-diabetes', q: 'Blood glucose reading usually treated as hypoglycemia?', a: 'Below 70 mg/dL in a symptomatic patient (some protocols use 60).' },
  { id: 'car-oral-glucose', d: 'cardiac', n: 'ch22-ams-diabetes', q: 'Three criteria for oral glucose?', a: 'History of diabetes, altered mental status, and awake enough to swallow and protect the airway. Commonly one 15 g tube between cheek and gum.' },
  { id: 'car-glucose-unsure', d: 'cardiac', n: 'ch22-ams-diabetes', q: 'Diabetic with AMS, and you cannot tell high from low sugar. Give glucose?', a: 'Yes, if they can swallow — glucose helps a low and does no meaningful harm to a high.' },
  { id: 'car-hypo-vs-hyper', d: 'cardiac', n: 'ch22-ams-diabetes', q: 'Hypoglycemia vs. hyperglycemia: onset and skin?', a: 'Hypoglycemia: rapid onset, cool pale clammy skin. Hyperglycemia: slow onset (days), warm dry skin, possible fruity breath and deep rapid (Kussmaul) breathing.' },
  { id: 'car-dka', d: 'cardiac', n: 'ch22-ams-diabetes', q: 'Diabetic ketoacidosis: three signs that point to it?', a: 'Deep, rapid (Kussmaul) respirations, fruity/acetone breath, and signs of dehydration (thirst, frequent urination).' },
  { id: 'car-type1-2', d: 'cardiac', n: 'ch22-ams-diabetes', q: 'Type 1 vs. type 2 diabetes?', a: 'Type 1: the pancreas makes no insulin; insulin is required. Type 2: the cells do not use insulin properly; diet, oral medication, sometimes insulin.' },
  { id: 'car-mimic', d: 'cardiac', n: 'ch22-ams-diabetes', q: 'A "drunk" patient with slurred speech and staggering — what must you rule out?', a: 'Hypoglycemia (and head injury, stroke, hypoxia). Check the blood glucose.' },
  { id: 'car-seizure-care', d: 'cardiac', n: 'ch22-seizure-stroke-syncope', q: 'During a tonic-clonic seizure: what do you do and not do?', a: 'Protect from injury, move objects away, loosen tight clothing. Do not restrain the patient or put anything in the mouth. Afterwards: airway, suction, recovery position if no spinal injury, oxygen as needed.' },
  { id: 'car-status', d: 'cardiac', n: 'ch22-seizure-stroke-syncope', q: 'Define status epilepticus.', a: 'A seizure lasting longer than 5 minutes, or two or more seizures without regaining full consciousness between them. Life-threatening: transport immediately, consider ALS.' },
  { id: 'car-seizure-cause', d: 'cardiac', n: 'ch22-seizure-stroke-syncope', q: 'Most common cause of a seizure in an adult with known epilepsy?', a: 'Missed or inadequate doses of their anti-seizure medication.' },
  { id: 'car-stroke-types', d: 'cardiac', n: 'ch22-seizure-stroke-syncope', q: 'Ischemic vs. hemorrhagic stroke?', a: 'Ischemic (most common): a clot blocks an artery. Hemorrhagic: a vessel ruptures, often from hypertension or an aneurysm.' },
  { id: 'car-tia', d: 'cardiac', n: 'ch22-seizure-stroke-syncope', q: 'Stroke symptoms that went away in 20 minutes — TIA. How do you treat it?', a: 'As a stroke: you cannot tell them apart in the field, and a TIA warns of a stroke to come. Transport.' },
  { id: 'car-lkw', d: 'cardiac', n: 'ch22-seizure-stroke-syncope', q: 'Most valuable piece of history in a suspected stroke?', a: 'The time last known well (symptom onset). Clot-busting treatment typically needs to start within 3–4.5 hours.' },
  { id: 'car-stroke-mimic', d: 'cardiac', n: 'ch22-seizure-stroke-syncope', q: 'Common stroke mimics?', a: 'Hypoglycemia (check glucose), a postictal state after a seizure, and infection or sepsis in older adults.' },
  { id: 'car-stroke-o2', d: 'cardiac', n: 'ch22-seizure-stroke-syncope', q: 'Oxygen for a stroke patient?', a: 'Only if SpO₂ is below 94% or the patient is in respiratory distress.' },
  { id: 'car-syncope', d: 'cardiac', n: 'ch22-seizure-stroke-syncope', q: 'Why is syncope taken seriously even after the patient recovers?', a: 'A cardiac cause (dysrhythmia) or hidden bleeding (GI bleed, ectopic pregnancy, AAA) may be behind it. Most syncope patients should be evaluated by ALS and transported.' },
  { id: 'car-anaphylaxis-def', d: 'cardiac', n: 'ch23-allergic', q: 'What turns an allergic reaction into anaphylaxis?', a: 'Respiratory distress or signs of shock (either one is enough), usually with widespread hives or swelling.' },
  { id: 'car-epi-dose', d: 'cardiac', n: 'ch23-allergic', q: 'Epinephrine auto-injector doses?', a: 'Adult 0.3 mg; child under about 30 kg (66 lb) 0.15 mg. Into the outer thigh, intramuscular.' },
  { id: 'car-epi-how', d: 'cardiac', n: 'ch23-allergic', q: 'How is an epinephrine auto-injector given, and when do you reassess?', a: 'Check the expiration, remove the safety cap, press firmly into the outer thigh midway between hip and knee and hold until injected. Reassess in about 2 minutes; a second dose needs medical direction.' },
  { id: 'car-epi-action', d: 'cardiac', n: 'ch23-allergic', q: 'Why is epinephrine the drug for anaphylaxis?', a: 'It acts on alpha receptors (vasoconstriction, raises BP, reduces swelling) and beta receptors (bronchodilation) at once.' },
  { id: 'car-epi-side', d: 'cardiac', n: 'ch23-allergic', q: 'Side effects of epinephrine?', a: 'Increased heart rate and blood pressure, anxiety, tremor, pallor; chest pain in some patients.' },
  { id: 'car-naloxone', d: 'cardiac', n: 'ch18-pharmacology', q: 'Naloxone: what it reverses, and the route an EMT uses?', a: 'Opioid-induced respiratory depression. Intranasal (commonly a 4 mg spray) or IM, per protocol. Ventilate with a BVM first — breathing comes before the antidote.' },
  { id: 'car-opioid', d: 'cardiac', n: 'ch25-substance-abuse', q: 'Opioid toxidrome?', a: 'Depressed breathing, decreased level of consciousness, pinpoint pupils.' },
  { id: 'car-naloxone-after', d: 'cardiac', n: 'ch25-substance-abuse', q: 'Why monitor closely after naloxone wakes the patient?', a: 'It can wear off before the opioid does, and it can cause sudden withdrawal (vomiting, agitation, combativeness).' },
  { id: 'car-sympath', d: 'cardiac', n: 'ch25-substance-abuse', q: 'Stimulant (sympathomimetic) toxidrome?', a: 'Agitation, tachycardia, hypertension, dilated pupils, sweating, high temperature — e.g. cocaine, methamphetamine.' },
  { id: 'car-anticholinergic', d: 'cardiac', n: 'ch25-ingested-inhaled', q: 'Anticholinergic toxidrome, the memory aid?', a: 'Hot as a hare, dry as a bone, red as a beet, blind as a bat (dilated pupils), mad as a hatter — plus tachycardia and urinary retention.' },
  { id: 'car-co', d: 'cardiac', n: 'ch25-ingested-inhaled', q: 'Clues to carbon monoxide poisoning?', a: 'Headache, nausea, dizziness or confusion, often in several people or pets in one building, especially in cold weather. Remove from the source, high-flow oxygen.' },
  { id: 'car-charcoal', d: 'cardiac', n: 'ch25-ingested-inhaled', q: 'Activated charcoal: when is it not given?', a: 'Altered mental status or inability to swallow, and ingestions of acids, alkalis or petroleum products. It is system-dependent and needs medical direction.' },
  { id: 'car-poison-center', d: 'cardiac', n: 'ch25-ingested-inhaled', q: 'Poison Control number in the US?', a: '1-800-222-1222.' },
  { id: 'car-ingestion-hx', d: 'cardiac', n: 'ch25-ingested-inhaled', q: 'Four questions about any poisoning?', a: 'What was taken, how much, when, and by what route — and bring the container.' },
  { id: 'car-organophos', d: 'cardiac', n: 'ch25-ingested-inhaled', q: 'Organophosphate exposure: the first priority?', a: 'Your own safety and decontamination — it absorbs through skin. Then airway: heavy secretions and bronchospasm are what kill.' },
  { id: 'car-alcohol-w', d: 'cardiac', n: 'ch25-substance-abuse', q: 'Severe alcohol withdrawal (delirium tremens): signs?', a: 'Confusion, hallucinations, tremors, sweating, tachycardia, seizures, beginning a day or more after the last drink. Life-threatening.' },
  { id: 'car-sepsis', d: 'cardiac', n: 'ch24-sepsis', q: 'Signs that suggest sepsis?', a: 'Suspected infection with fever or low temperature, fast heart rate, fast breathing, altered mental status or hypotension. Older adults may have no fever.' },
  { id: 'car-ppe-tb', d: 'cardiac', n: 'ch24-communicable', q: 'Suspected tuberculosis: what PPE protects you?', a: 'An N95 (or higher) respirator, and a surgical mask on the patient.' },
  { id: 'car-appendix', d: 'cardiac', n: 'ch26-abdominal', q: 'Appendicitis: classic pain pattern?', a: 'Starts around the umbilicus, then settles in the right lower quadrant; with fever, nausea, loss of appetite.' },
  { id: 'car-gallbladder', d: 'cardiac', n: 'ch26-abdominal', q: 'Cholecystitis: where is the pain?', a: 'Right upper quadrant, often referred to the right shoulder, frequently after a fatty meal.' },
  { id: 'car-referred', d: 'cardiac', n: 'ch26-abdominal', q: 'Kehr sign?', a: 'Pain in the left shoulder from blood irritating the diaphragm, classically a ruptured spleen.' },
  { id: 'car-abd-care', d: 'cardiac', n: 'ch26-assessment', q: 'Care for a patient with acute abdominal pain?', a: 'Nothing by mouth, position of comfort (often knees bent), treat for shock, transport. Diagnosis is not the EMT’s job; recognizing shock is.' },
  { id: 'car-gi-bleed', d: 'cardiac', n: 'ch26-abdominal', q: 'Signs of upper GI bleeding?', a: 'Vomiting blood or "coffee-ground" material, and dark tarry stools (melena).' },
  { id: 'car-dialysis', d: 'cardiac', n: 'ch28-renal', q: 'Dialysis patient with a fistula in one arm: which arm for BP?', a: 'The other arm. Never take a BP or apply a tourniquet on the fistula arm.' },
  { id: 'car-missed-dialysis', d: 'cardiac', n: 'ch28-renal', q: 'Danger of a missed dialysis session?', a: 'Fluid overload (pulmonary edema) and high potassium, which can cause dangerous dysrhythmias and cardiac arrest.' },
  { id: 'car-sickle', d: 'cardiac', n: 'ch28-hematologic', q: 'Sickle cell crisis: what happens and what do you do?', a: 'Sickled cells block small vessels: severe pain, risk of stroke, infection and acute chest syndrome. Oxygen as needed, comfort, transport.' },
  { id: 'car-hypothermia-stages', d: 'cardiac', n: 'ch35-cold', q: 'Mild vs. severe hypothermia: the key decision point?', a: 'Mild: shivering, still alert. Severe (core below about 90°F/32°C): shivering stops, mental status falls. Severe hypothermia needs gentle handling — rough movement can trigger VF.' },
  { id: 'car-hypothermia-care', d: 'cardiac', n: 'ch35-cold', q: 'Care for a hypothermic patient?', a: 'Remove from the cold, take off wet clothing, insulate, warm passively (and actively only per protocol), handle gently, nothing to eat or drink, transport.' },
  { id: 'car-hypothermia-arrest', d: 'cardiac', n: 'ch21-special', q: 'Hypothermic cardiac arrest: shocks and termination?', a: 'Defibrillate as for any arrest — withholding shocks by temperature is no longer advised. Do not terminate in the field: "not dead until warm and dead."' },
  { id: 'car-heat', d: 'cardiac', n: 'ch35-heat-water', q: 'Heat exhaustion vs. heat stroke: the deciding findings?', a: 'Heat stroke: altered mental status with hot skin (dry or still sweating) — a life threat. Heat exhaustion: mental status normal or only mildly affected, skin cool or normal and moist.' },
  { id: 'car-heatstroke-care', d: 'cardiac', n: 'ch35-heat-water', q: 'Heat stroke: main treatment?', a: 'Rapid, aggressive cooling (remove clothing, cool water, fanning, ice packs to groin, armpits and neck) and transport.' },
  { id: 'car-frostbite', d: 'cardiac', n: 'ch35-cold', q: 'Frostbite: two things you never do?', a: 'Never rub or massage the area, and never rewarm it if it could refreeze.' },
  { id: 'car-drowning', d: 'cardiac', n: 'ch35-heat-water', q: 'Drowning arrest: what is the priority?', a: 'Ventilation — the arrest is asphyxial. Give rescue breaths and good-quality CPR; dry the chest before using an AED.' },
  { id: 'car-dcs', d: 'cardiac', n: 'ch35-heat-water', q: 'Decompression sickness ("the bends") vs. arterial gas embolism?', a: 'Gas embolism comes on within minutes of surfacing (stroke-like, sudden). Decompression sickness usually appears hours later (joint pain, rash, neurologic symptoms). Both need oxygen and a hyperbaric chamber.' },
  { id: 'car-snake', d: 'cardiac', n: 'ch35-bites-stings', q: 'Pit viper bite: what do you do and avoid?', a: 'Keep the patient calm and still, remove rings, keep the limb immobilized at about heart level, mark the edge of swelling, transport. No tourniquet, ice, cutting or suction.' },
  { id: 'car-widow', d: 'cardiac', n: 'ch35-bites-stings', q: 'Black widow vs. brown recluse bite?', a: 'Black widow: neurotoxic — severe muscle cramps, rigid abdomen. Brown recluse: local tissue destruction that develops over days.' },
  { id: 'car-lightning', d: 'cardiac', n: 'ch35-heat-water', q: 'Lightning strike with several victims: who is treated first?', a: 'Those who appear dead (reverse triage). Arrest from lightning is often survivable with prompt CPR, and those still moving are likely to live.' },
  { id: 'car-behavioral-safety', d: 'cardiac', n: 'ch27-behavioral-assessment', q: 'Behavioral emergency: your first priority?', a: 'Scene safety. Keep an exit route, do not get between the patient and the door, and wait for law enforcement if there is danger.' },
  { id: 'car-suicide', d: 'cardiac', n: 'ch27-behavioral-assessment', q: 'Should you ask a patient directly whether they are thinking about suicide?', a: 'Yes. Asking directly does not plant the idea; ask about a plan and the means. Do not leave a suicidal patient alone.' },
  { id: 'car-restraint', d: 'cardiac', n: 'ch27-restraint', q: 'Restraining a violent patient: key safety rules?', a: 'Enough people (at least four or five), reasonable force only, never prone or hobbled, monitor airway and breathing continuously, document why and how.' },
  { id: 'car-medic-5rights', d: 'cardiac', n: 'ch18-pharmacology', q: 'The five rights of medication administration?', a: 'Right patient, right medication, right dose, right route, right time — and check the expiration date.' },
  { id: 'car-online-offline', d: 'cardiac', n: 'ch18-pharmacology', q: 'Online vs. offline medical direction?', a: 'Online: live orders by radio or phone (repeat them back). Offline: standing orders and protocols written in advance.' },
  { id: 'car-routes', d: 'cardiac', n: 'ch18-pharmacology', q: 'Which drug route is slowest, and why can sublingual fail in shock?', a: 'Oral (swallowed) is slowest because it must be digested. Sublingual absorption depends on circulation, which shock reduces.' },
  { id: 'car-generic', d: 'cardiac', n: 'ch18-pharmacology', q: 'Generic vs. trade name — which is capitalized?', a: 'The trade (brand) name, e.g. Ventolin. The generic name is lowercase: albuterol.' },
  { id: 'car-indication', d: 'cardiac', n: 'ch18-pharmacology', q: 'Side effect vs. untoward effect?', a: 'A side effect is any action other than the intended one; an untoward effect is a side effect that harms.' },
  { id: 'car-hypertensive', d: 'cardiac', n: 'ch20-cad-ami-hf', q: 'Signs of a hypertensive emergency?', a: 'Very high BP with severe headache, confusion, visual changes, nausea, chest pain or seizures. Transport; do not try to lower the pressure yourself.' },

  /* ---------------- Trauma ---------------- */
  { id: 'tra-bleed-types', d: 'trauma', n: 'ch29-bleeding-control', q: 'Arterial, venous and capillary bleeding — how do they look?', a: 'Arterial: bright red, spurting with the pulse. Venous: dark red, steady flow. Capillary: dark red ooze, usually stops on its own.' },
  { id: 'tra-blood-volume', d: 'trauma', n: 'ch29-bleeding-control', q: 'Sudden blood loss that is serious in an adult, a child and an infant?', a: 'Adult about 1 L (of roughly 5 L); child about 500 mL; infant as little as 100–200 mL.' },
  { id: 'tra-direct-pressure', d: 'trauma', n: 'ch29-bleeding-control', q: 'First step for most external bleeding?', a: 'Firm direct pressure over the wound. If a dressing soaks through, add more on top rather than removing it.' },
  { id: 'tra-tq-when', d: 'trauma', n: 'ch29-tourniquets', q: 'When does a tourniquet go on?', a: 'Immediately for life-threatening extremity bleeding, or when direct pressure fails. It is not a last resort.' },
  { id: 'tra-tq-where', d: 'trauma', n: 'ch29-tourniquets', q: 'Where and how tight is a tourniquet applied?', a: 'High and tight on the limb, or 2–3 inches above the wound and not over a joint; tightened until the bleeding stops and the distal pulse is gone. Add a second above the first if one is not enough.' },
  { id: 'tra-tq-record', d: 'trauma', n: 'ch29-tourniquets', q: 'After applying a tourniquet, what must be recorded — and may you loosen it?', a: 'Record the time applied (and that it is on). Do not loosen or remove it in the field.' },
  { id: 'tra-packing', d: 'trauma', n: 'ch29-tourniquets', q: 'Wound packing: how is it done?', a: 'Pack gauze (plain or hemostatic) firmly into the wound down to the bleeding source, filling the cavity, then hold firm pressure for at least 3 minutes.' },
  { id: 'tra-no-pack', d: 'trauma', n: 'ch29-tourniquets', q: 'Which wounds are never packed?', a: 'Chest, abdomen and head wounds — packing can push into a body cavity or the brain.' },
  { id: 'tra-nosebleed', d: 'trauma', n: 'ch29-bleeding-control', q: 'Care for a nosebleed?', a: 'Sit the patient up leaning forward and pinch the soft part of the nostrils together for 10–15 minutes. Do not tilt the head back (blood is swallowed or aspirated).' },
  { id: 'tra-shock-early', d: 'trauma', n: 'ch29-internal-bleeding', q: 'Early signs of shock?', a: 'Anxiety or restlessness, tachycardia, pale cool clammy skin, thirst, rising respiratory rate, delayed capillary refill — while BP is still normal.' },
  { id: 'tra-shock-late', d: 'trauma', n: 'ch29-internal-bleeding', q: 'Why is falling blood pressure a late sign of shock?', a: 'Compensation (faster heart, vasoconstriction) holds BP up until it fails. Once BP drops, the patient is decompensating.' },
  { id: 'tra-shock-care', d: 'trauma', n: 'ch29-internal-bleeding', q: 'Care for hemorrhagic shock in the field?', a: 'Control external bleeding, oxygen as needed, keep the patient warm, lay them flat, handle gently, rapid transport to a trauma center.' },
  { id: 'tra-internal', d: 'trauma', n: 'ch29-internal-bleeding', q: 'How do you recognize internal bleeding?', a: 'Signs of shock with no external bleeding to explain them — plus bruising, a tender or swollen abdomen, coughed or vomited blood, or a long-bone or pelvic injury.' },
  { id: 'tra-femur-pelvis', d: 'trauma', n: 'ch29-internal-bleeding', q: 'Roughly how much blood can a femur fracture hold? A pelvic fracture?', a: 'A femur fracture can hold well over a liter; a pelvic fracture can hold far more.' },
  { id: 'tra-neurogenic', d: 'trauma', n: 'ch33-cord-injury', q: 'Neurogenic shock vs. hemorrhagic shock?', a: 'Neurogenic: low BP with a normal or slow heart rate and warm, dry, flushed skin below the injury. Hemorrhagic: low BP with tachycardia and pale, cool, clammy skin.' },
  { id: 'tra-cushing', d: 'trauma', n: 'ch33-tbi', q: 'Cushing triad (rising intracranial pressure)?', a: 'Rising blood pressure (widening pulse pressure), falling heart rate, and irregular breathing.' },
  { id: 'tra-basilar', d: 'trauma', n: 'ch33-tbi', q: 'Signs of a basilar skull fracture?', a: 'Bruising around the eyes (raccoon eyes), bruising behind the ears (Battle sign), and clear fluid (CSF) from the nose or ears.' },
  { id: 'tra-csf', d: 'trauma', n: 'ch33-tbi', q: 'Clear fluid draining from the ear after a head injury: pack it?', a: 'No. Cover loosely with sterile gauze; do not stop the flow.' },
  { id: 'tra-epidural', d: 'trauma', n: 'ch33-tbi', q: 'Epidural hematoma: classic course?', a: 'Brief loss of consciousness, a "lucid interval" when the patient seems fine, then rapid deterioration — arterial bleeding.' },
  { id: 'tra-subdural', d: 'trauma', n: 'ch33-tbi', q: 'Subdural hematoma: who and how fast?', a: 'Venous bleeding, so it can develop slowly over hours to days — common in older adults, heavy drinkers and people on blood thinners.' },
  { id: 'tra-tbi-secondary', d: 'trauma', n: 'ch33-tbi', q: 'What causes secondary brain injury that an EMT can prevent?', a: 'Hypoxia and hypotension (and hypo- or hyperventilation). Keep oxygenation and BP up; ventilate at the normal rate unless protocol says otherwise.' },
  { id: 'tra-pupils', d: 'trauma', n: 'ch33-tbi', q: 'A head-injured patient has one dilated, sluggish pupil. Significance?', a: 'Pressure on the brain (possible herniation) — a critical, rapidly worsening injury.' },
  { id: 'tra-nexus', d: 'trauma', n: 'ch33-head-neck-spine', q: 'NEXUS-type criteria: when is spinal motion restriction needed after trauma?', a: 'Any of: midline spinal tenderness, a neurologic deficit, altered mental status, intoxication, or a painful distracting injury (and for some protocols, an age-related risk).' },
  { id: 'tra-cord-level', d: 'trauma', n: 'ch33-cord-injury', q: 'Why is a cervical spinal cord injury at C3–C5 so dangerous?', a: 'The phrenic nerve (C3, 4, 5) drives the diaphragm — "C3, 4, 5 keeps the diaphragm alive." Injury here can stop breathing.' },
  { id: 'tra-helmet', d: 'trauma', n: 'ch33-head-neck-spine', q: 'When is a helmet removed?', a: 'When it blocks airway management or ventilation, does not hold the head snugly, or you need to do CPR. Otherwise leave it on and stabilize it.' },
  { id: 'tra-neck-wound', d: 'trauma', n: 'ch33-head-neck-spine', q: 'Open wound to the neck: what dressing, and why?', a: 'An occlusive dressing with direct pressure — air sucked into a large vein can cause an air embolism. Do not compress both sides of the neck.' },
  { id: 'tra-open-ptx', d: 'trauma', n: 'ch31-chest', q: 'Sucking chest wound: what goes on it?', a: 'An occlusive dressing (vented chest seal if available, or one taped on three sides). Watch for a tension pneumothorax.' },
  { id: 'tra-tension', d: 'trauma', n: 'ch31-chest', q: 'Signs of a tension pneumothorax?', a: 'Worsening respiratory distress, absent breath sounds on one side, hypotension, jugular vein distention; tracheal deviation is a late sign.' },
  { id: 'tra-tension-fix', d: 'trauma', n: 'ch31-chest', q: 'A patient with a sealed chest wound gets worse and shows signs of tension. EMT action?', a: 'Lift (burp) a corner of the occlusive dressing to let air escape, then reseal; support breathing and call ALS.' },
  { id: 'tra-flail', d: 'trauma', n: 'ch31-chest', q: 'Flail chest: definition and sign?', a: 'Two or more adjacent ribs each broken in two or more places; the segment moves opposite to the rest of the chest (paradoxical motion). Oxygen and assisted ventilation as needed.' },
  { id: 'tra-tamponade', d: 'trauma', n: 'ch31-chest', q: 'Beck triad (cardiac tamponade)?', a: 'Hypotension, jugular vein distention and muffled heart sounds.' },
  { id: 'tra-commotio', d: 'trauma', n: 'ch31-chest', q: 'Commotio cordis?', a: 'Cardiac arrest (VF) from a blunt blow to the chest at the wrong moment of the heartbeat — e.g. a baseball. Early defibrillation.' },
  { id: 'tra-evisc', d: 'trauma', n: 'ch31-abdomen', q: 'Abdominal evisceration: care?', a: 'Do not push the organs back. Cover with a moist sterile dressing, then an occlusive dressing; keep the patient warm, knees bent if no spinal injury.' },
  { id: 'tra-impaled', d: 'trauma', n: 'ch30-wounds', q: 'Impaled object: when may it be removed?', a: 'Only if it is through the cheek and blocks the airway, or it prevents CPR. Otherwise stabilize it in place with bulky dressings.' },
  { id: 'tra-amputation', d: 'trauma', n: 'ch30-wounds', q: 'Care of an amputated part?', a: 'Wrap it in sterile gauze (dry or lightly moistened per protocol), seal it in a plastic bag, and keep it cool — not in direct contact with ice. Transport it with the patient.' },
  { id: 'tra-closed-wounds', d: 'trauma', n: 'ch30-wounds', q: 'Closed soft-tissue injuries: three types?', a: 'Contusion (bruise), hematoma (pooled blood), and crush injury.' },
  { id: 'tra-crush', d: 'trauma', n: 'ch30-wounds', q: 'Why can releasing a long-trapped crushed limb be dangerous?', a: 'Crush syndrome: toxins and potassium from damaged muscle reach the circulation suddenly, causing dysrhythmias and cardiac arrest. Call ALS before release where possible.' },
  { id: 'tra-dressing', d: 'trauma', n: 'ch30-burns', q: 'Dressing vs. bandage?', a: 'A dressing covers the wound and controls bleeding; a bandage holds the dressing in place.' },
  { id: 'tra-burn-depth', d: 'trauma', n: 'ch30-burns', q: 'Superficial, partial-thickness and full-thickness burns?', a: 'Superficial (1st degree): red, painful. Partial (2nd): blisters, very painful. Full (3rd): dry, leathery, white or charred, may be painless.' },
  { id: 'tra-burn-center', d: 'trauma', n: 'ch30-burns', q: 'Burns that need a burn center?', a: 'Partial-thickness over 10% of body surface; any full-thickness burn; burns of the face, hands, feet, genitals, perineum or major joints; electrical, chemical or inhalation burns; circumferential burns; burns with other trauma or in high-risk patients.' },
  { id: 'tra-burn-care', d: 'trauma', n: 'ch30-burns', q: 'First steps for a thermal burn?', a: 'Stop the burning: remove the patient from the source, cool with clean, cool water (never ice; keep it brief on a large burn, which risks hypothermia), remove jewelry, cover with dry sterile dressings and keep the patient warm.' },
  { id: 'tra-chem-burn', d: 'trauma', n: 'ch30-burns', q: 'Chemical burn from a dry powder: first step?', a: 'Brush the dry chemical off, then flush with large amounts of flowing water for at least 20 minutes, continuing en route.' },
  { id: 'tra-electrical', d: 'trauma', n: 'ch30-burns', q: 'Electrical burn: the hidden dangers?', a: 'Extensive internal injury between entry and exit wounds, and cardiac dysrhythmias or arrest. Make sure the power is off before you touch the patient.' },
  { id: 'tra-airway-burn', d: 'trauma', n: 'ch30-burns', q: 'Signs of an airway burn?', a: 'Singed facial or nasal hair, soot around the mouth or in sputum, hoarseness, stridor — the airway can swell shut quickly.' },
  { id: 'tra-fx-types', d: 'trauma', n: 'ch32-msk', q: 'Open vs. closed fracture?', a: 'Open: the skin over it is broken (bone may or may not show). Closed: the skin is intact.' },
  { id: 'tra-splint-rule', d: 'trauma', n: 'ch32-msk', q: 'Splinting rules?', a: 'Immobilize the joint above and below a fracture (the bones above and below a joint injury); check pulse, motor and sensation before and after; pad the splint; splint in the position found unless the limb is pulseless.' },
  { id: 'tra-traction', d: 'trauma', n: 'ch32-msk', q: 'Traction splint: when is it used, and when not?', a: 'Used for an isolated mid-shaft femur fracture. Not with hip or pelvic fractures, knee injuries, lower-leg or ankle injuries, or a partial amputation.' },
  { id: 'tra-pelvic-binder', d: 'trauma', n: 'ch32-msk', q: 'Suspected pelvic fracture: what do you do and not do?', a: 'Apply a pelvic binder over the greater trochanters; do not rock or spring the pelvis to test it.' },
  { id: 'tra-compartment', d: 'trauma', n: 'ch32-msk', q: 'Compartment syndrome: the earliest sign?', a: 'Pain out of proportion to the injury (especially on passive stretch). The six Ps: pain, pallor, paresthesia, pulselessness, paralysis, and pressure (or poikilothermia).' },
  { id: 'tra-dislocation', d: 'trauma', n: 'ch32-msk', q: 'Dislocated joint with no distal pulse: realign it?', a: 'Follow protocol; generally splint in the position found and transport rapidly. Check pulse, motor and sensation repeatedly.' },
  { id: 'tra-golden', d: 'trauma', n: 'ch34-multisystem', q: 'Target on-scene time for a critical trauma patient?', a: 'About 10 minutes ("platinum 10") — the definitive treatment is surgery, so get moving.' },
  { id: 'tra-fall-height', d: 'trauma', n: 'ch15-secondary-assessment', q: 'Significant fall height under the current national field triage guideline?', a: 'More than 10 feet (3 m), for all ages. Older guidance taught 20 feet for adults.' },
  { id: 'tra-high-risk-crash', d: 'trauma', n: 'ch34-multisystem', q: 'High-risk crash criteria?', a: 'Ejection, death in the same passenger compartment, significant intrusion (more than 12 inches at the occupant site, 18 anywhere), child unrestrained or in an unsecured car seat, and a pedestrian or cyclist thrown, run over or struck with significant impact.' },
  { id: 'tra-frontal', d: 'trauma', n: 'ch34-multisystem', q: 'Frontal collision: "up and over" vs. "down and under" injuries?', a: 'Up and over: head, neck, chest and abdomen (steering wheel, windshield). Down and under: knees, femurs, hips and pelvis (dashboard).' },
  { id: 'tra-three-collisions', d: 'trauma', n: 'ch34-multisystem', q: 'The three collisions in a crash?', a: 'The vehicle hits the object; the body hits the inside of the vehicle; the organs hit the inside of the body.' },
  { id: 'tra-penetrating', d: 'trauma', n: 'ch31-chest', q: 'Gunshot wound: what do you look for besides the entry?', a: 'An exit wound and any internal path — the visible hole tells you little about the damage inside.' },
  { id: 'tra-eye-impaled', d: 'trauma', n: 'ch30-wounds', q: 'Object impaled in the eye: care?', a: 'Stabilize it (a cup over it), cover both eyes to limit movement, and transport. Do not remove it.' },
  { id: 'tra-chemical-eye', d: 'trauma', n: 'ch30-burns', q: 'Chemical splashed in the eye: care?', a: 'Flush with clean water continuously, from the inner corner outward, for at least 20 minutes and en route.' },
  { id: 'tra-avulsed-tooth', d: 'trauma', n: 'ch30-wounds', q: 'Knocked-out tooth: how do you transport it?', a: 'Handle it by the crown, not the root; keep it moist (milk, saline or a tooth-preservation solution) and bring it.' },
  { id: 'tra-geriatric-trauma', d: 'trauma', n: 'ch34-multisystem', q: 'Why are older trauma patients undertriaged?', a: 'Weaker bones and fragile vessels mean worse injury from smaller forces; medications such as beta-blockers can mask tachycardia; blood thinners increase bleeding.' },

  /* ---------------- OB/Peds & Special Populations ---------------- */
  { id: 'ob-stages', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'The three stages of labor?', a: '1st: onset of contractions to full cervical dilation. 2nd: full dilation to delivery of the baby. 3rd: delivery of the placenta.' },
  { id: 'ob-imminent', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'Signs that delivery is imminent?', a: 'Crowning, contractions about 2 minutes apart or less, a strong urge to push or to move the bowels, and a history of rapid deliveries.' },
  { id: 'ob-supine-hypo', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'Supine hypotensive syndrome: cause and fix?', a: 'Late in pregnancy, the uterus compresses the inferior vena cava when she lies flat. Position her on her left side (or tilt or displace the uterus to the left).' },
  { id: 'ob-physiology', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'Pregnancy changes that affect your assessment?', a: 'Blood volume up by as much as half and heart rate up about 10–20/min, so signs of blood loss appear late; slower stomach emptying raises vomiting and aspiration risk.' },
  { id: 'ob-nuchal', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'Cord wrapped around the baby’s neck at delivery?', a: 'Gently slip it over the head. If it cannot be loosened, clamp it in two places and cut between the clamps.' },
  { id: 'ob-shoulders', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'Delivering the shoulders?', a: 'Guide the head gently downward to deliver the upper shoulder, then upward for the lower shoulder. Support the slippery baby.' },
  { id: 'ob-cord-clamp', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'When should the umbilical cord be clamped in a vigorous newborn?', a: 'Delay it in a vigorous newborn — about 60 seconds or more after birth, per current neonatal guidance and local protocol. Then two clamps, and cut between them.' },
  { id: 'ob-newborn-first', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'First steps for every newborn?', a: 'Dry, warm and stimulate; position the airway; clear secretions only if they block the airway or the baby needs ventilation.' },
  { id: 'ob-newborn-ppv', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'Newborn is apneic or gasping, or heart rate under 100. What and how fast?', a: 'Positive-pressure ventilation with a BVM at 40–60 breaths per minute.' },
  { id: 'ob-newborn-cpr', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'Newborn heart rate under 60 despite effective ventilation: compressions how?', a: 'Two thumbs encircling the chest, 3 compressions to 1 breath.' },
  { id: 'ob-meconium', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'Meconium-stained fluid and a non-vigorous baby: routine deep suction first?', a: 'No — routine suctioning is no longer recommended. Start the normal steps and ventilate if needed; suction only if the airway is obstructed.' },
  { id: 'ob-placenta', d: 'obpeds', n: 'ch36-pregnancy-labor', q: 'Delivering the placenta: pull on the cord?', a: 'Never. Let it deliver on its own (usually within 30 minutes), bring it to the hospital, and do not delay transport for it.' },
  { id: 'ob-pph', d: 'obpeds', n: 'ch36-complications', q: 'Bleeding after delivery: how much is too much, and what helps?', a: 'More than about 500 mL is postpartum hemorrhage. Fundal (uterine) massage, letting the baby breastfeed, treat for shock and transport.' },
  { id: 'ob-prolapsed', d: 'obpeds', n: 'ch36-complications', q: 'Prolapsed umbilical cord: care?', a: 'Hips elevated (knee-chest or head-down position), gloved fingers in the vagina to push the presenting part off the cord, keep the cord moist, do not push it back in, rapid transport.' },
  { id: 'ob-breech', d: 'obpeds', n: 'ch36-complications', q: 'Breech delivery and the head does not deliver?', a: 'Make an airway: gloved fingers in a V on either side of the baby’s nose, holding the vaginal wall away from the face, and transport rapidly.' },
  { id: 'ob-limb', d: 'obpeds', n: 'ch36-complications', q: 'An arm or leg presents first. Can you deliver in the field?', a: 'No. Do not pull. Position the mother (hips elevated), give oxygen as needed and transport immediately.' },
  { id: 'ob-previa-abruption', d: 'obpeds', n: 'ch36-complications', q: 'Placenta previa vs. placental abruption?', a: 'Previa: painless bright red bleeding. Abruption: sudden abdominal pain with a rigid uterus; bleeding may be dark or hidden.' },
  { id: 'ob-ectopic', d: 'obpeds', n: 'ch36-complications', q: 'Ectopic pregnancy: presentation?', a: 'One-sided lower abdominal pain, a missed period, vaginal bleeding and signs of shock — consider it in any woman of childbearing age with abdominal pain.' },
  { id: 'ob-preeclampsia', d: 'obpeds', n: 'ch36-complications', q: 'Preeclampsia vs. eclampsia?', a: 'Preeclampsia: high blood pressure after 20 weeks with headache, visual changes, swelling. Eclampsia: the same plus seizures. Keep the patient calm, lights low, left side, transport.' },
  { id: 'ob-arrest', d: 'obpeds', n: 'ch36-complications', q: 'CPR on a visibly pregnant patient: the extra step?', a: 'Manually displace the uterus to her left during compressions, so it does not compress the vena cava.' },
  { id: 'ob-trauma', d: 'obpeds', n: 'ch36-complications', q: 'Pregnant trauma patient: whom do you resuscitate first?', a: 'The mother. Her circulation is the baby’s; give oxygen and tilt or displace the uterus to the left.' },
  { id: 'ob-sexual-assault', d: 'obpeds', n: 'ch36-complications', q: 'Sexual assault patient: how do you preserve evidence?', a: 'Discourage bathing, changing clothes, urinating or brushing teeth; bag any clothing separately in paper bags; limit the exam to what care requires.' },
  { id: 'peds-bp-formula', d: 'obpeds', n: 'ch8-lifespan', q: 'Lower limit of normal systolic BP in a child aged 1–10?', a: '70 + (2 × age in years) mmHg.' },
  { id: 'peds-compensate', d: 'obpeds', n: 'ch8-lifespan', q: 'Why is a normal BP in a sick child not reassuring?', a: 'Children compensate very well and then crash suddenly; hypotension is a late, ominous sign. Tachycardia and delayed capillary refill come first.' },
  { id: 'peds-brady', d: 'obpeds', n: 'ch21-steps', q: 'A bradycardic, sick child: what is the usual cause and the fix?', a: 'Hypoxia. Oxygenate and ventilate; compressions if the rate stays under 60 with poor perfusion.' },
  { id: 'peds-asphyxial', d: 'obpeds', n: 'ch21-arrest-pathophys', q: 'Why do pediatric arrests need good ventilation?', a: 'Most pediatric arrests are asphyxial (respiratory failure or shock), not sudden dysrhythmias.' },
  { id: 'peds-cap-refill', d: 'obpeds', n: 'ch13-taking-vitals', q: 'Capillary refill: normal value, and where is it most useful?', a: 'Under 2 seconds. Most reliable in children under about 6.' },
  { id: 'peds-dehydration', d: 'obpeds', n: 'ch8-lifespan', q: 'Signs of dehydration in an infant?', a: 'Sunken fontanelle, no tears, dry mouth, fewer wet diapers, lethargy, tachycardia.' },
  { id: 'peds-fontanelle', d: 'obpeds', n: 'ch8-lifespan', q: 'Bulging fontanelle in a quiet infant suggests?', a: 'Raised intracranial pressure (e.g. meningitis, head injury).' },
  { id: 'peds-febrile', d: 'obpeds', n: 'ch22-seizure-stroke-syncope', q: 'Febrile seizure: what causes it, and is it an emergency?', a: 'A rapid rise in temperature in a young child. Usually brief, but always transport for evaluation — the fever may be from a serious infection such as meningitis.' },
  { id: 'peds-sids', d: 'obpeds', n: 'ch21-special', q: 'Suspected SUID with no rigor mortis or dependent lividity: resuscitate?', a: 'Yes. And support the family without a suspicious tone; SIDS happens to well-cared-for babies.' },
  { id: 'peds-abuse', d: 'obpeds', n: 'ch37-abuse', q: 'Findings that suggest child abuse?', a: 'Injuries that do not fit the story or the child’s development, injuries of different ages, patterned bruises or burns, delay in seeking care, caregivers whose stories change.' },
  { id: 'peds-report', d: 'obpeds', n: 'ch37-abuse', q: 'Suspected child abuse: what is the EMT’s duty?', a: 'Treat the child, report the suspicion as your state requires (EMTs are mandated reporters in most states), and document objectively. Do not accuse or confront.' },
  { id: 'peds-shaken', d: 'obpeds', n: 'ch37-abuse', q: 'Shaken baby syndrome: what may you find?', a: 'An irritable or lethargic infant, vomiting, seizures, breathing problems, often with few outward signs of injury.' },
  { id: 'peds-adolescent', d: 'obpeds', n: 'ch8-lifespan', q: 'Interviewing an adolescent: a key courtesy?', a: 'Privacy. Where you can, ask about sensitive matters (drugs, sex, pregnancy) away from parents.' },
  { id: 'peds-infant-hypothermia', d: 'obpeds', n: 'ch8-lifespan', q: 'Why do infants lose heat so quickly?', a: 'Large surface area for their size and a large head; keep them covered, especially the head.' },
  { id: 'peds-broselow', d: 'obpeds', n: 'ch18-pharmacology', q: 'What does a length-based tape (Broselow) give you?', a: 'Estimated weight, equipment sizes and drug doses from the child’s length.' },
  { id: 'peds-car-seat', d: 'obpeds', n: 'ch38-operating', q: 'Transporting a child safely?', a: 'In a size-appropriate restraint system secured to the stretcher or a seat — never in a parent’s arms.' },
  { id: 'peds-airway-fb', d: 'obpeds', n: 'ch9-fbao', q: 'A toddler with sudden coughing, wheezing and no fever while playing — think of?', a: 'A foreign-body aspiration.' },
  { id: 'geri-physio', d: 'obpeds', n: 'ch8-lifespan', q: 'Older adults: why are infections and MIs easy to miss?', a: 'Blunted responses: fever may be absent, pain may be absent or vague, and confusion may be the only sign.' },
  { id: 'geri-falls', d: 'obpeds', n: 'ch8-lifespan', q: 'An older adult who fell: what else do you ask?', a: 'Why they fell — syncope, dysrhythmia, stroke, low blood sugar, new medications — and whether they take blood thinners.' },
  { id: 'geri-polypharmacy', d: 'obpeds', n: 'ch8-lifespan', q: 'Polypharmacy?', a: 'Taking many medications at once, which raises the risk of interactions, side effects and dosing errors. Bring the medications or a list.' },
  { id: 'geri-abuse', d: 'obpeds', n: 'ch37-abuse', q: 'Signs of elder abuse or neglect?', a: 'Unexplained injuries, poor hygiene, malnutrition, untreated pressure sores, a caregiver who will not let the patient speak — report as required.' },
  { id: 'geri-delirium', d: 'obpeds', n: 'ch8-lifespan', q: 'Delirium vs. dementia?', a: 'Delirium: sudden, fluctuating confusion with a medical cause (infection, hypoxia, drugs) — an emergency. Dementia: gradual, long-term decline.' },
  { id: 'spec-autism', d: 'obpeds', n: 'ch37-special-challenges', q: 'Approaching a patient with autism?', a: 'Calm, low stimulation (quiet, dim lights), simple direct language, ask caregivers what works, explain before you touch, allow time.' },
  { id: 'spec-hearing', d: 'obpeds', n: 'ch37-special-challenges', q: 'Communicating with a deaf or hard-of-hearing patient?', a: 'Face them so they can read your lips, speak clearly without shouting, use writing or an interpreter, and ask how they prefer to communicate.' },
  { id: 'spec-vp-shunt', d: 'obpeds', n: 'ch37-devices', q: 'Ventricular (VP) shunt: what does a failure look like?', a: 'Signs of raised intracranial pressure: headache, vomiting, altered mental status, irritability, bulging fontanelle in an infant.' },
  { id: 'spec-feeding-tube', d: 'obpeds', n: 'ch37-devices', q: 'Patient with a feeding tube: positioning in transport?', a: 'Head elevated (sitting or about 30°) to reduce the risk of aspiration.' },
  { id: 'spec-central-line', d: 'obpeds', n: 'ch37-devices', q: 'Bleeding from a central venous catheter site: what do you do?', a: 'Direct pressure. If the line is broken, clamp or kink it above the break; watch for air embolism.' },
  { id: 'spec-bariatric', d: 'obpeds', n: 'ch37-special-challenges', q: 'Bariatric patient: airway positioning?', a: 'Ramp the head and shoulders up (ear level with the sternum); they desaturate quickly when flat.' },
  { id: 'spec-hospice', d: 'obpeds', n: 'ch4-dnr-ethics', q: 'Hospice patient in distress with a valid DNR: what can you still do?', a: 'Comfort care: oxygen, positioning, suction, emotional support. A DNR limits resuscitation, not care.' },
  { id: 'spec-trafficking', d: 'obpeds', n: 'ch37-abuse', q: 'Possible signs of human trafficking?', a: 'A patient who is not allowed to speak for themselves, does not hold their own ID, seems fearful or coached, or gives inconsistent stories. Treat, document and report through proper channels.' },

  /* ---------------- Assessment ---------------- */
  { id: 'as-order', d: 'assessment', n: 'ch12-primary-assessment', q: 'Patient assessment in order?', a: 'Scene size-up, primary assessment, history taking, secondary assessment, reassessment.' },
  { id: 'as-scene-first', d: 'assessment', n: 'ch11-scene-size-up', q: 'First question of every scene size-up?', a: 'Is it safe? Then standard precautions, number of patients, mechanism or nature of illness, and additional resources.' },
  { id: 'as-moi-noi', d: 'assessment', n: 'ch11-scene-size-up', q: 'MOI vs. NOI?', a: 'Mechanism of injury (how the trauma patient was hurt) vs. nature of illness (what the medical patient is experiencing).' },
  { id: 'as-resources', d: 'assessment', n: 'ch11-scene-size-up', q: 'When do you call for more resources?', a: 'During the size-up, as soon as you see the need — more patients than you can handle, hazards, extrication, ALS — before you get absorbed in patient care.' },
  { id: 'as-general', d: 'assessment', n: 'ch12-primary-assessment', q: 'What is the general impression?', a: 'Your first look as you approach: age, sex, the chief complaint, how sick the patient looks, and any obvious life threat.' },
  { id: 'as-primary', d: 'assessment', n: 'ch12-primary-assessment', q: 'Primary assessment components?', a: 'General impression and level of consciousness, then airway, breathing, circulation (pulse, major bleeding, skin), and a transport decision. Life-threatening bleeding is controlled as soon as it is found.' },
  { id: 'as-xabc', d: 'assessment', n: 'ch12-primary-assessment', q: 'Unresponsive, not breathing, no pulse: what changes in the primary assessment?', a: 'It becomes C-A-B: start chest compressions right away.' },
  { id: 'as-aox4', d: 'assessment', n: 'ch12-primary-assessment', q: 'Oriented ×4 means oriented to what?', a: 'Person, place, time and event.' },
  { id: 'as-vitals-adult', d: 'assessment', n: 'ch13-taking-vitals', q: 'Normal adult vital signs at rest?', a: [['Pulse', '60–100/min'], ['Respirations', '12–20/min'], ['Systolic BP', 'about 90–140 mmHg']] },
  { id: 'as-skin', d: 'assessment', n: 'ch13-taking-vitals', q: 'Three skin findings you assess, and what pale, cool and moist means?', a: 'Color, temperature, moisture (condition). Pale, cool, moist skin suggests poor perfusion — shock.' },
  { id: 'as-skin-color', d: 'assessment', n: 'ch13-taking-vitals', q: 'Where do you check skin color in a patient with dark skin?', a: 'Mucous membranes: inside the lips and lower eyelids, and the nail beds.' },
  { id: 'as-bp-palp', d: 'assessment', n: 'ch13-vital-signs', q: 'BP by palpation gives which number?', a: 'Systolic only.' },
  { id: 'as-bp-cuff', d: 'assessment', n: 'ch13-vital-signs', q: 'A BP cuff that is too small reads high or low?', a: 'Falsely high (too large reads falsely low).' },
  { id: 'as-pulse-pressure', d: 'assessment', n: 'ch13-vital-signs', q: 'Pulse pressure: narrowing vs. widening?', a: 'Narrowing (systolic and diastolic closer together) suggests shock or tamponade; widening suggests rising intracranial pressure.' },
  { id: 'as-orthostatic', d: 'assessment', n: 'ch13-vital-signs', q: 'Positive orthostatic vital signs?', a: 'On standing or sitting up, a heart-rate rise of about 20/min or more or a systolic drop of about 20 mmHg or more, or dizziness — suggests volume loss.' },
  { id: 'as-spo2-limit', d: 'assessment', n: 'ch13-vital-signs', q: 'When is a pulse oximeter reading unreliable?', a: 'Carbon monoxide poisoning, poor peripheral perfusion (shock, cold), nail polish, severe anemia, excessive motion.' },
  { id: 'as-glucometer', d: 'assessment', n: 'ch13-vital-signs', q: 'Glucometer: why wipe away the first drop?', a: 'It may be contaminated with alcohol or tissue fluid. Use the second drop.' },
  { id: 'as-pupils', d: 'assessment', n: 'ch13-taking-vitals', q: 'Pinpoint pupils vs. dilated pupils: think of?', a: 'Pinpoint: opioids, some poisons. Dilated: stimulants, hypoxia, fear. Unequal: head injury or stroke (or a normal variant).' },
  { id: 'as-reassess', d: 'assessment', n: 'ch16-reassessment', q: 'How often do you reassess vital signs?', a: 'Every 5 minutes for an unstable patient, every 15 minutes for a stable one.' },
  { id: 'as-trending', d: 'assessment', n: 'ch16-reassessment', q: 'Why do two sets of vitals beat one?', a: 'The trend shows whether the patient is improving or deteriorating; a single number cannot.' },
  { id: 'as-pertinent-neg', d: 'assessment', n: 'ch14-principles-assessment', q: 'What is a pertinent negative?', a: 'An expected finding that is absent and worth recording — e.g. chest pain with no shortness of breath.' },
  { id: 'as-sign-symptom', d: 'assessment', n: 'ch14-principles-assessment', q: 'Sign vs. symptom — which is objective?', a: 'A sign (seen, heard, felt or measured). A symptom is what the patient reports.' },
  { id: 'as-chief', d: 'assessment', n: 'ch14-principles-assessment', q: 'Chief complaint?', a: 'The main reason the patient called, in their own words.' },
  { id: 'as-open-closed', d: 'assessment', n: 'ch14-principles-assessment', q: 'Open-ended vs. closed questions?', a: 'Open-ended let the patient describe ("Tell me about the pain"); closed get a yes, no or a fact ("Does it spread to your arm?").' },
  { id: 'as-rapid-exam', d: 'assessment', n: 'ch15-secondary-assessment', q: 'Rapid full-body scan vs. focused exam: when each?', a: 'Rapid scan: significant mechanism or unresponsive patient. Focused exam: an isolated injury or a responsive medical patient with a specific complaint.' },
  { id: 'as-medical-unresp', d: 'assessment', n: 'ch15-secondary-assessment', q: 'Unresponsive medical patient: where does the history come from?', a: 'Family, bystanders, medical alert tags, medications in the home — after the rapid exam and vitals.' },
  { id: 'as-jvd', d: 'assessment', n: 'ch15-secondary-assessment', q: 'Distended neck veins in a patient sitting up suggest?', a: 'Back-pressure into the venous system: heart failure, tension pneumothorax or cardiac tamponade.' },
  { id: 'as-lung-sites', d: 'assessment', n: 'ch14-principles-assessment', q: 'Where do you listen to breath sounds at minimum?', a: 'Both sides, at the apices (upper chest) and bases (lower back or midaxillary line), comparing side to side.' },
  { id: 'as-quadrants', d: 'assessment', n: 'ch26-assessment', q: 'Main organs in each abdominal quadrant?', a: [['RUQ', 'Liver, gallbladder'], ['LUQ', 'Stomach, spleen'], ['RLQ', 'Appendix'], ['LLQ', 'Sigmoid colon']] },
  { id: 'as-palpate', d: 'assessment', n: 'ch26-assessment', q: 'Which abdominal quadrant do you palpate first?', a: 'The one farthest from the pain, ending with the painful area.' },
  { id: 'as-resp-patterns', d: 'assessment', n: 'ch19-respiratory', q: 'Kussmaul vs. Cheyne-Stokes respirations?', a: 'Kussmaul: deep, rapid breathing (metabolic acidosis, e.g. DKA). Cheyne-Stokes: rising and falling depth with pauses (brain injury, stroke, end of life).' },
  { id: 'as-decorticate', d: 'assessment', n: 'ch33-tbi', q: 'Decorticate vs. decerebrate posturing?', a: 'Decorticate: arms flexed in toward the core. Decerebrate: arms extended and rotated — the worse of the two.' },
  { id: 'as-gcs8', d: 'assessment', n: 'ch12-primary-assessment', q: 'GCS of 8 or less signals?', a: 'A severely depressed level of consciousness and an airway that may not protect itself.' },
  { id: 'as-anatomical', d: 'assessment', n: 'ch5-terminology', q: 'Anatomical position?', a: 'Standing, facing forward, arms at the sides, palms forward. Left and right are the patient’s.' },
  { id: 'as-medial', d: 'assessment', n: 'ch5-terminology', q: 'Medial vs. lateral?', a: 'Medial: closer to the midline. Lateral: farther from it.' },
  { id: 'as-superior', d: 'assessment', n: 'ch5-terminology', q: 'Superior vs. inferior; anterior vs. posterior?', a: 'Superior: toward the head; inferior: toward the feet. Anterior: front; posterior: back.' },
  { id: 'as-recovery', d: 'assessment', n: 'ch14-principles-assessment', q: 'Recovery position: who and why?', a: 'An unresponsive patient who is breathing adequately and has no suspected spinal injury: on their side, so fluids drain from the mouth.' },
  { id: 'as-handoff', d: 'assessment', n: 'ch17-pcr', q: 'What goes in a verbal handoff report?', a: 'Name and age, chief complaint, history, findings and vitals, treatment given and the response to it, and any change during transport.' },
  { id: 'as-radio-report', d: 'assessment', n: 'ch17-radio', q: 'Radio report to the hospital — contents?', a: 'Unit and level, ETA, age and sex, chief complaint, brief history, mental status, vitals, key findings, care given and response.' },
  { id: 'as-pcr', d: 'assessment', n: 'ch17-pcr', q: 'Why is a complete PCR so important?', a: 'It is the legal record and the hospital’s handoff. If it was not documented, it was not done.' },
  { id: 'as-pcr-error', d: 'assessment', n: 'ch17-pcr', q: 'You find an error in a paper PCR. How do you correct it?', a: 'Draw a single line through it, initial and date it, and write the correct information. Never erase or black it out.' },
  { id: 'as-soap', d: 'assessment', n: 'ch17-pcr', q: 'SOAP narrative format?', a: 'Subjective (what the patient says), Objective (what you find), Assessment (your impression), Plan (treatment and transport).' },
  { id: 'as-quotes', d: 'assessment', n: 'ch17-pcr', q: 'How do you record what the patient said?', a: 'In quotation marks, in the patient’s own words, especially for anything legally significant.' },
  { id: 'as-elderly-comm', d: 'assessment', n: 'ch17-pcr', q: 'Therapeutic communication basics?', a: 'Introduce yourself, use the patient’s name, get to eye level, speak clearly and honestly, listen, and explain what you are doing.' },
  { id: 'as-chest-pain-hx', d: 'assessment', n: 'ch14-principles-assessment', q: 'Which mnemonic explores a complaint of pain?', a: 'OPQRST — onset, provocation, quality, radiation, severity, time.' },
  { id: 'as-lob', d: 'assessment', n: 'ch14-principles-assessment', q: 'What does SAMPLE gather?', a: 'Signs and symptoms, allergies, medications, pertinent past history, last oral intake, events leading up.' },

  /* ---------------- EMS Operations ---------------- */
  { id: 'op-scope', d: 'operations', n: 'ch4-scope-consent', q: 'Scope of practice vs. standard of care?', a: 'Scope of practice: what an EMT is legally allowed to do. Standard of care: how a reasonably prudent EMT with similar training would act in similar circumstances.' },
  { id: 'op-consent-expressed', d: 'operations', n: 'ch4-scope-consent', q: 'Expressed consent?', a: 'Given by a competent adult, in words or actions, after being told what you plan to do and why.' },
  { id: 'op-consent-implied', d: 'operations', n: 'ch4-scope-consent', q: 'Implied consent?', a: 'Assumed for an unresponsive (or incapacitated) patient with a life-threatening condition — they would agree if they could.' },
  { id: 'op-minor', d: 'operations', n: 'ch4-scope-consent', q: 'Treating a minor: whose consent?', a: 'A parent or legal guardian’s; in a true emergency with no guardian present, implied consent. Emancipated minors consent for themselves.' },
  { id: 'op-refusal', d: 'operations', n: 'ch4-scope-consent', q: 'Requirements for a valid refusal?', a: 'A competent adult (alert, not impaired), informed of the risks of refusing, including death; encouraged to accept care; told to call back; signed and witnessed, and documented fully.' },
  { id: 'op-competence', d: 'operations', n: 'ch4-scope-consent', q: 'Who cannot legally refuse care?', a: 'A patient lacking decision-making capacity — altered mental status, intoxication, head injury, hypoxia, hypoglycemia — and most minors.' },
  { id: 'op-abandon', d: 'operations', n: 'ch4-negligence-confidentiality', q: 'Abandonment?', a: 'Ending care without handing the patient to someone of equal or higher training, or without the patient’s consent.' },
  { id: 'op-negligence', d: 'operations', n: 'ch4-negligence-confidentiality', q: 'Four elements of negligence?', a: 'Duty to act, breach of that duty, damages (harm), and proximate cause (the breach caused the harm).' },
  { id: 'op-assault-battery', d: 'operations', n: 'ch4-negligence-confidentiality', q: 'Assault vs. battery?', a: 'Assault: making someone fear unwanted contact. Battery: touching them without consent.' },
  { id: 'op-false-imprison', d: 'operations', n: 'ch4-negligence-confidentiality', q: 'False imprisonment?', a: 'Confining or transporting a competent patient against their will without legal authority.' },
  { id: 'op-hipaa', d: 'operations', n: 'ch4-negligence-confidentiality', q: 'When may you share patient information without consent?', a: 'With other providers involved in the patient’s care, for billing, when subpoenaed or legally required (e.g. mandated reports). Not with the press, friends or the public.' },
  { id: 'op-good-sam', d: 'operations', n: 'ch4-negligence-confidentiality', q: 'What do Good Samaritan laws do?', a: 'Protect people who help in good faith, without pay, within their training — they do not protect gross negligence.' },
  { id: 'op-duty', d: 'operations', n: 'ch4-negligence-confidentiality', q: 'When does an EMT have a duty to act?', a: 'When on duty and dispatched or responding (and in some states whenever in uniform or by contract). Off duty, the legal duty depends on state law.' },
  { id: 'op-dnr', d: 'operations', n: 'ch4-dnr-ethics', q: 'A family member says the patient has a DNR, but nobody can find it. What do you do?', a: 'Begin resuscitation. A DNR must be valid and present (or per protocol); contact medical direction if in doubt.' },
  { id: 'op-polst', d: 'operations', n: 'ch4-dnr-ethics', q: 'What is a POLST (or MOLST)?', a: 'A physician order that travels with the patient and sets out which treatments they want — resuscitation, intubation, hospitalization, comfort care.' },
  { id: 'op-obvious-death', d: 'operations', n: 'ch4-dnr-ethics', q: 'Signs of obvious death that allow you to withhold CPR?', a: 'Decapitation, rigor mortis, dependent lividity, decomposition, and injuries clearly incompatible with life.' },
  { id: 'op-crime-scene', d: 'operations', n: 'ch4-negligence-confidentiality', q: 'Care at a crime scene: how do you protect evidence?', a: 'Patient care first, but touch only what you must, do not cut through holes in clothing, note what you moved, and keep a single path in and out.' },
  { id: 'op-mandatory', d: 'operations', n: 'ch4-negligence-confidentiality', q: 'What must EMTs typically report?', a: 'Suspected abuse of children, elders or dependent adults, injuries from violent crime (such as gunshot wounds), certain infectious diseases, and other state-specific events.' },
  { id: 'op-standard-prec', d: 'operations', n: 'ch2-provider-wellness', q: 'Standard precautions assume what?', a: 'That every patient’s blood and body fluids may be infectious — so wear gloves, and add eye protection, mask or gown as the risk of splash requires.' },
  { id: 'op-handwash', d: 'operations', n: 'ch2-provider-wellness', q: 'Most effective single way to prevent the spread of infection?', a: 'Hand hygiene — washing with soap and water (or alcohol rub when hands are not visibly soiled), before and after every patient.' },
  { id: 'op-exposure', d: 'operations', n: 'ch2-provider-wellness', q: 'Needlestick or blood splash: what do you do?', a: 'Wash the area (flush eyes or mucous membranes), report it immediately to your supervisor or infection-control officer, and get prompt medical evaluation.' },
  { id: 'op-hepb', d: 'operations', n: 'ch2-provider-wellness', q: 'Which bloodborne infection has a vaccine EMTs should get?', a: 'Hepatitis B.' },
  { id: 'op-grief', d: 'operations', n: 'ch2-stress-safety', q: 'Kübler-Ross stages of grief?', a: 'Denial, anger, bargaining, depression, acceptance — not always in order.' },
  { id: 'op-stress-signs', d: 'operations', n: 'ch2-stress-safety', q: 'Signs of cumulative stress in an EMT?', a: 'Irritability, poor sleep, fatigue, loss of interest, trouble concentrating, increased alcohol use. Seek support; employee assistance programs exist for this.' },
  { id: 'op-power-lift', d: 'operations', n: 'ch3-lifting-moving', q: 'Key rules of the power lift?', a: 'Feet shoulder-width apart, back locked straight, lift with the legs, keep the weight close to your body, no twisting, and communicate with your partner.' },
  { id: 'op-power-grip', d: 'operations', n: 'ch3-lifting-moving', q: 'Power grip?', a: 'Palms up, all fingers bent to the same angle around the handle, hands at least 10 inches apart.' },
  { id: 'op-reach', d: 'operations', n: 'ch3-lifting-moving', q: 'Safe reaching distance?', a: 'Not more than about 20 inches (50 cm) in front of your body, back locked, no twisting.' },
  { id: 'op-emergency-move', d: 'operations', n: 'ch3-lifting-moving', q: 'When is an emergency move justified?', a: 'Immediate danger (fire, explosion, traffic, hazmat), when you cannot reach or treat a life threat where the patient lies, or to reach a more critical patient.' },
  { id: 'op-drag', d: 'operations', n: 'ch3-lifting-moving', q: 'In an emergency move, how do you protect the spine?', a: 'Drag along the long axis of the body (clothes, blanket or shoulder drag), never sideways.' },
  { id: 'op-rapid-ext', d: 'operations', n: 'ch3-lifting-moving', q: 'Rapid extrication vs. a vest-type device: when is rapid extrication used?', a: 'When the patient is unstable or the scene is unsafe — there is no time for a short immobilization device.' },
  { id: 'op-call-phases', d: 'operations', n: 'ch38-ambulance-readiness', q: 'Phases of an ambulance call?', a: 'Nine: preparation; dispatch; en route to the scene; arrival at the scene; transfer of the patient to the ambulance; en route to the receiving facility; at the receiving facility; en route to the station; post-run.' },
  { id: 'op-due-regard', d: 'operations', n: 'ch38-operating', q: 'With lights and siren on, may you ignore traffic laws?', a: 'Only within limits your state allows, and always with due regard for the safety of others. You are still liable for crashes you cause.' },
  { id: 'op-intersection', d: 'operations', n: 'ch38-operating', q: 'Where do most ambulance crashes happen?', a: 'At intersections. Come to a complete stop at red lights and stop signs, and make eye contact with other drivers before proceeding.' },
  { id: 'op-siren', d: 'operations', n: 'ch38-operating', q: 'Does a siren make other drivers safe?', a: 'No. Drivers often do not hear it until close, and sirens raise the stress of everyone, including the patient. Use it only when needed.' },
  { id: 'op-highway-park', d: 'operations', n: 'ch40-highway', q: 'Highway crash: how are arriving units positioned?', a: 'A blocking vehicle (usually a fire engine) parks upstream at an angle to shield the scene. The ambulance parks downstream, past the crash, inside the protected zone, with its loading doors away from traffic. Units not needed at the scene stage off the roadway until called.' },
  { id: 'op-vest', d: 'operations', n: 'ch40-highway', q: 'PPE required when working near traffic?', a: 'A high-visibility, ANSI-compliant reflective safety vest.' },
  { id: 'op-power-lines', d: 'operations', n: 'ch40-highway', q: 'Downed power line on a vehicle: what do you do?', a: 'Treat it as energized. Stay well clear, keep others away, tell the occupants to stay inside, and wait for the utility company.' },
  { id: 'op-airbag', d: 'operations', n: 'ch40-extrication', q: 'Undeployed airbag: safe distances?', a: 'The 5-10-20 rule: 5 inches from side bags, 10 inches from the driver’s, 20 inches from the passenger’s.' },
  { id: 'op-stabilize', d: 'operations', n: 'ch40-extrication', q: 'First step before entering a crashed vehicle?', a: 'Stabilize it (cribbing, wheel chocks, put it in park, turn off the ignition) so it cannot move.' },
  { id: 'op-access', d: 'operations', n: 'ch40-extrication', q: 'Gaining access: simple before complex?', a: 'Try the doors first ("try before you pry"), then windows. Complex access with tools comes after.' },
  { id: 'op-lz-size', d: 'operations', n: 'ch38-operating', q: 'Helicopter landing zone size?', a: 'About 100 feet by 100 feet, on a slope under 8 degrees, clear of wires, towers, vehicles and loose objects.' },
  { id: 'op-lz-approach', d: 'operations', n: 'ch38-operating', q: 'How do you approach a helicopter?', a: 'Only when signaled by the crew, from the front where the pilot can see you, crouched, never from the rear (tail rotor) and never from uphill.' },
  { id: 'op-air-when', d: 'operations', n: 'ch38-operating', q: 'When does air medical transport make sense?', a: 'When ground transport to the needed facility would take too long for a time-critical patient (major trauma, stroke, STEMI), or the patient is inaccessible.' },
  { id: 'op-hazmat-zones', d: 'operations', n: 'ch39-hazmat', q: 'Hazmat control zones?', a: 'Hot (exclusion): the contaminated area. Warm (contamination reduction): decontamination. Cold (support): command, staging and treatment — where EMTs work unless trained for more.' },
  { id: 'op-hazmat-approach', d: 'operations', n: 'ch39-hazmat', q: 'Approaching a possible hazmat scene?', a: 'Upwind and uphill, from a distance; use binoculars to read placards; do not enter until trained responders say it is safe.' },
  { id: 'op-erg', d: 'operations', n: 'ch39-hazmat', q: 'What is the Emergency Response Guidebook?', a: 'The DOT guide that identifies a hazardous material by its UN/NA number or name and gives initial actions and isolation distances.' },
  { id: 'op-erg-colors', d: 'operations', n: 'ch39-hazmat', q: 'ERG sections by page color?', a: 'Yellow: by ID number. Blue: by name. Orange: guide pages (actions). Green: isolation and protective-action distances.' },
  { id: 'op-decon', d: 'operations', n: 'ch39-hazmat', q: 'Who is decontaminated before EMS treatment?', a: 'Every exposed patient leaves the warm zone through decontamination before reaching EMS in the cold zone.' },
  { id: 'op-mci', d: 'operations', n: 'ch39-mci-ics', q: 'What defines a multiple-casualty incident?', a: 'Any event with more patients than the responding resources can handle with normal procedures.' },
  { id: 'op-ics-sections', d: 'operations', n: 'ch39-mci-ics', q: 'ICS: the general staff sections under Command?', a: 'Operations, Planning, Logistics, and Finance/Administration.' },
  { id: 'op-ics-command', d: 'operations', n: 'ch39-mci-ics', q: 'Who is incident commander at an MCI?', a: 'The first arriving qualified responder establishes command until relieved by someone more senior. Unified command is used when several agencies share authority.' },
  { id: 'op-span', d: 'operations', n: 'ch39-mci-ics', q: 'Span of control in ICS?', a: 'Each supervisor manages about 3 to 7 people (5 is ideal).' },
  { id: 'op-ems-roles', d: 'operations', n: 'ch39-mci-ics', q: 'EMS branch roles at an MCI?', a: 'Triage, treatment, transportation and staging supervisors (officers), plus a rehabilitation area for responders.' },
  { id: 'op-triage-colors', d: 'operations', n: 'ch39-mci-ics', q: 'Triage tag colors?', a: 'Red: immediate. Yellow: delayed. Green: minor (walking wounded). Black: deceased (or expectant in SALT).' },
  { id: 'op-start-walk', d: 'operations', n: 'ch39-mci-ics', q: 'START: first step?', a: 'Tell everyone who can walk to move to a set area. They are tagged green (minor) and reassessed later.' },
  { id: 'op-start-resp', d: 'operations', n: 'ch39-mci-ics', q: 'START: a patient is not breathing. What next?', a: 'Reposition the airway once. Still not breathing: deceased (black). Breathing after repositioning: immediate (red).' },
  { id: 'op-start-30', d: 'operations', n: 'ch39-mci-ics', q: 'START: respiratory rate over 30?', a: 'Immediate (red).' },
  { id: 'op-start-perf', d: 'operations', n: 'ch39-mci-ics', q: 'START: what makes perfusion "immediate"?', a: 'No radial pulse or capillary refill over 2 seconds.' },
  { id: 'op-start-mental', d: 'operations', n: 'ch39-mci-ics', q: 'START: the patient breathes under 30 and has a radial pulse but cannot follow simple commands.', a: 'Immediate (red). If they can follow commands: delayed (yellow).' },
  { id: 'op-start-treat', d: 'operations', n: 'ch39-mci-ics', q: 'Which treatments are allowed during START triage?', a: 'Only quick life-saving ones: opening the airway and controlling major bleeding (e.g. a tourniquet). Then move on.' },
  { id: 'op-jumpstart', d: 'operations', n: 'ch39-mci-ics', q: 'JumpSTART (children): apneic child who has a pulse?', a: 'Give 5 rescue breaths. Breathing resumes: immediate. Still apneic: deceased.' },
  { id: 'op-jumpstart-rr', d: 'operations', n: 'ch39-mci-ics', q: 'JumpSTART: respiratory rate cut-offs for immediate?', a: 'Under 15 or over 45 breaths per minute.' },
  { id: 'op-staging', d: 'operations', n: 'ch39-mci-ics', q: 'Why use a staging area at an MCI?', a: 'Arriving ambulances wait there until called, so the scene does not jam and patients are distributed sensibly among hospitals.' },
  { id: 'op-911', d: 'operations', n: 'ch1-911', q: 'What does enhanced 911 add?', a: 'The caller’s phone number and location appear automatically at the dispatch center.' },
  { id: 'op-emd', d: 'operations', n: 'ch38-ambulance-readiness', q: 'What does an emergency medical dispatcher do beyond sending a unit?', a: 'Asks structured questions to prioritize the call and gives pre-arrival instructions (e.g. CPR or bleeding control) to the caller.' },
  { id: 'op-levels', d: 'operations', n: 'ch1-ems-systems-roles', q: 'The four national EMS provider levels?', a: 'Emergency Medical Responder (EMR), EMT, Advanced EMT (AEMT) and Paramedic.' },
  { id: 'op-med-director', d: 'operations', n: 'ch1-education-qi', q: 'Under whose authority does an EMT give care?', a: 'The medical director’s. EMTs hold their own certification or license but act as designated agents of the physician who oversees the service.' },
  { id: 'op-qi', d: 'operations', n: 'ch1-education-qi', q: 'What is continuous quality improvement (CQI)?', a: 'Ongoing review of calls and outcomes to find and fix problems in the system — not to punish individuals.' },
  { id: 'op-radio-echo', d: 'operations', n: 'ch17-radio', q: 'How do you confirm a radio order from medical direction?', a: 'Repeat it back word for word (the echo technique), and ask for clarification if it seems wrong.' },
  { id: 'op-radio-plain', d: 'operations', n: 'ch17-radio', q: 'Radio etiquette?', a: 'Think before you key, press the button and wait a second before speaking, keep it brief, use plain English, and never give a patient’s name over the air.' },
  { id: 'op-cleaning', d: 'operations', n: 'ch38-ambulance-readiness', q: 'Cleaning vs. disinfecting vs. sterilizing?', a: 'Cleaning removes dirt; disinfecting kills many microorganisms on surfaces; sterilizing kills all of them (e.g. heat, for items that enter the body).' },
  { id: 'op-transfer', d: 'operations', n: 'ch38-operating', q: 'At the hospital, when does your responsibility end?', a: 'When you have given a verbal report and handed the patient over to someone of equal or higher training who accepts care.' },
  { id: 'op-terrorism', d: 'operations', n: 'ch39-hazmat', q: 'Suspected terrorist or WMD scene: what do you assume?', a: 'A possible secondary device or attack aimed at responders. Stage at a safe distance, stay upwind, watch for unusual patterns of illness.' },
];
